custom_css:
/*——有bug的话，调💽的数值，💿是次选调动。
不要商用二传，可以小幅度二改，我会高强度自搜的。
以上！  by：阿遥/Lyo——*/

/*字体*/
@import url("https://fontsapi.zeoseven.com/183/main/result.css");

body {
    font-family: "极影毁片辉宋 Bold";
    font-weight: normal;
}


/*顶栏*/
#top-bar {
    position: fixed;
    pointer-events: none;
    z-index: 1; 
    background: none;
    border: 0;
    background-color: transparent !important;
    box-shadow: none;
    overflow: visible;
}


#top-bar::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    border: 0px solid rgba(255, 255, 255, 1);
    border-radius: 0px;
    background: rgba(0, 0, 0, 0.7);
    z-index: -1;
}


/*图标*/
#top-settings-holder .drawer-icon{
  opacity: 0.8; 
}

/* 平滑过渡 */
#top-settings-holder .drawer-icon::before {
  vertical-align: middle;
  transition: transform 0.3s ease-in-out, color 0.2s ease-in-out;
  display: inline-block;
  font-size: 24px; 
}

/* 导航关闭状态 */
#top-settings-holder .drawer-icon.closedIcon::before {
  content: '' !important; 
  transform: rotate(0deg);
}

/* 悬停效果 */
#top-settings-holder .drawer-icon:hover::before {
    transform: scale(1.2) rotate(15deg);
    transition: transform 0.2s ease-in-out;
}

/* 导航展开状态 */
#top-settings-holder .drawer-icon.openIcon::before {
  content: '' !important;  
  transform: rotate(180deg);
}

#top-settings-holder .drawer-icon{
   opacity: 1;
}

/* 基本设置 */
#top-settings-holder .drawer-icon::before {
  content: '' !important;
  display: inline-block;
  width: 20px;  
  height: 20px; 
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  transition: transform 0.3s ease-in-out, color 0.2s ease-in-out;
}

/* 关闭状态 */
#top-settings-holder .drawer-icon.closedIcon::before {
  background-image: url('https://iili.io/fG2azen.png') !important; 
  transform: scale(1.3);
  opacity: 0.1;
}

/* 展开状态 */
#top-settings-holder .drawer-icon.openIcon::before {
  background-image: url('https://iili.io/fG2auzG.png') !important; 
  transform: scale(1.5) rotate(0deg);
}


/* 隐藏滚动条 */
::-webkit-scrollbar {
    display: none;
}


/* =========================================
   1. 聊天气泡整体布局与间距
   ========================================= */
.mes {
  position: relative;
  z-index: -1;
  background-size: 100% auto; 
  background-attachment: local; 
  transition: transform 0.2s ease; 
  transform-origin: top center;
  max-width: 400px;/*💽气泡框大小*/
  margin: 200px auto 80px;/*💿次选调整*/
  background: url('空'); 
  overflow: visible;
  box-shadow: none !important; 
}

/* =========================================
   2. 头像 (Avatar) - 放大、旋转、独立
   ========================================= */
.mesAvatarWrapper {
    position: absolute !important;
    top: -50px !important;   /*💽上下*/
    left: 300px !important; /* 💽左右 */
    width: auto !important;
    height: auto !important;
    padding: 0 !important;
    margin: 0 !important;
    order: unset !important; 
    z-index: 10 !important; 
    box-shadow: none !important;
    filter: none !important;
}

.mesAvatarWrapper img {
    box-shadow: none !important;
    filter: none !important;
}

/* 头像放大旋转 */
.mesAvatarWrapper .avatar {
    transform: scale(2.5) rotate(15deg) !important;
    transform-origin: center center !important;
    max-width: unset !important;
    max-height: unset !important;
}

/* =========================================
   3. 解绑并移动 "三元素" (楼层、计时、词符)
   ========================================= */

/* 楼层数 (Floor ID) */
.mesIDDisplay {
    position: absolute !important;
    z-index: 9999;
    top: 78px !important;    /* 💽上下 */
    right: 290px !important;    /*💽 左右 */
    width: auto !important;
    margin: 0 !important; 
    color: #ffffff !important;
}

/* 回复计时 (Timer) */
.mes_timer {
  position: absolute; 
  z-index: 9999; 
  top: var(--element-top, 78px);
  left: var(--element-left, -185px);
  transform: translateX(var(--element-translate, -50%));
  transform: rotate(0deg); /* 旋转 */
  cursor: default;
  opacity: 1;/*透明度*/
  white-space: nowrap; 
  font-size: calc(var(--mainFontSize) * 1);/*大小*/
  font-weight: 0;/*粗细*/
  padding: 0;
  color: #fff !important;
}

.mes_timer::before {
    content: '';
    position: absolute;
    top: 0px !important;     /* 上下 */
    left: -10px !important;    /* 左右 */
    z-index: 9999;
}

/* 词符数 (Token Count) */
.tokenCounterDisplay {
  position: relative; 
  z-index: 9999; 
  top: 28px;
  left: -240px;
  transform: translateX(var(--element-translate, -50%));
  transform: rotate(0deg); /* 旋转 */
  cursor: default;
  opacity: 1;/*透明度*/
  white-space: nowrap; 
  font-size: calc(var(--mainFontSize) * 1);/*大小*/
  font-weight: 0;/*粗细*/
  padding: 0;
  color: #fff !important;
}


/* =========================================
   4. 解绑并移动 名字 和 时间
   ========================================= */
/* 名字 (Name) */
.name_text {
    position: absolute !important;
    z-index: 9999;
    transform: scale(1)  !important;
    top: 5px !important;    /* 上下 */
    left: 60px !important;    /* 左右 */
    width: auto !important;
    text-align: left !important;
    color: #fff !important;
}

/* 时间戳 (Timestamp) */
.timestamp {
    position: absolute !important;
    z-index: 9999;
    top: 50px !important;    /* 上下 */
    left: 80px !important;    /* 左右 */
    font-size: 0.8em !important; /* 稍微调小字体 */
    color: #ffffff !important;
}

/* 伪元素背景框 - 可以独立移动 */
.timestamp::before {
    content: '听歌时间:';
    position: absolute;
    top: 0px !important;     /* 向上移动5px */
    left: -52px !important;    /* 向左扩展8px */
    z-index: 9999;
}

/* =========================================
   5. 操作按钮 (小铅笔等)
   ========================================= */
.mes_buttons {
    position: absolute !important;
    z-index: 9999;
    top: 65px !important;    /* 上下 */
    right: 40px !important;    /* 左右 */
    color:#ffffff;
    opacity: 0.8; 
    flex-direction: row !important; 
}

.mes_edit_buttons {
    z-index: 9999;
    opacity: 1 !important;
    visibility: visible !important;
}

.mes:hover .mes_edit_buttons {
    opacity: 1 !important;
}


.mes_edit_buttons {
position: absolute !important;
    z-index: 9999;
    top: 65px !important;    /* 上下 */
    right: 40px !important;    /* 左右 */
    opacity: 0.8; 
    flex-direction: row !important; 
}


/* =========================================
   6. 文本框主体 (Text)
   ========================================= */
.mes_text {
    margin-left: 20px !important;     /* 左右 */
    margin-top: 60px !important;    /* 上下 */
    width: 100% !important;
    display: block;
    position: relative;
    z-index: 9999;
}


/*💽头像框*/
.mesAvatarWrapper {
  position: relative; 
  overflow: visible !important; 
}

.mesAvatarWrapper::after {
  content: '';
  position: absolute;
  top: 3px;/*💽向上拉伸*/
  left: -50px;/*💽向左拉伸*/
  right: -2px;/*💽向右拉伸*/
  bottom: -3px;/*💽向下拉伸*/
  transform: scale(2.8) rotate(-2deg) !important;/*💽调scale括号内，尽量小调*/
  background-image: url('https://iili.io/fG9EJus.png');
  background-size: contain;
  background-position: center;
  background-repeat: no-repeat;
  pointer-events: none;
}



/*💽装饰层*/
.mes::after {
  content: '';
  position: absolute;
  top: -60px;    /* 💽上下 */
  right: 2.8px;  /* 💽左右 */
  width: 390px;  /* 设置宽度 */
  height: 430px;  /* 设置高度 */
transform: translate(-50%, -50%);
  background-image: url('https://iili.io/fGHFRhx.png');
  background-size: contain;
  background-repeat: no-repeat;
  pointer-events: none; 
  transform: scale(1.095) rotate(0deg) !important;/*💽调scale括号内，尽量小调*/
  z-index: 1; 
}



/*💽下层装饰层*/
.mes::before {
    content: "";
    position: absolute;
    bottom: -90px; /*💽上下*/
    left: 6px; /*💽左右*/
    transform: translate(-50%, -50%);
    transform: scale(1.116) !important;/*💽调scale括号内，尽量小调*/
    background-image: url('https://iili.io/fGHmq6g.png');
    background-repeat: no-repeat;
    background-size: contain; 
    background-position: center top;
    width: 390px;  /* 设置宽度 */
    height: 100px; /* 设置高度 */
    margin-top: 0px; /* 图片与气泡框底部的间距 */
    z-index: 1; 
}


/*小铅笔、省略号图标*/
.fa-ellipsis-h::before,
.fa-ellipsis::before {
    content: "" !important;
    display: inline-block;
    width: 24px;
    height: 24px;
    background-image: url('https://iili.io/fGd2kKB.png');
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
}

.fa-pencil-alt::before,
.fa-pencil::before {
    content: "" !important;
    display: inline-block;
    width: 24px;
    height: 24px;
    background-image: url('https://iili.io/fGd2kKB.png');
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
}




/*底栏*/
#send_form {
    background-color: rgba(79, 126, 195, 0.75) !important;
    -webkit-backdrop-filter: blur(3px) !important; 
    backdrop-filter: blur(10px) !important;
    padding: 2px !important;
    border-radius: 20px !important;
    border: 1px solid rgba(255, 255, 255, 0.45) !important;/*边框*/
    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1) !important;/*阴影*/
}


/*底栏图标*/
#send_form [class*="fa-"]::before {
  content: '' !important;
  display: inline-block;
  width: 24px; /* 图片宽度 */
  height: 24px; /* 图片高度 */
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  vertical-align: middle;
}

/* 菜单 */
#options_button::before {
  background-image: url('https://iili.io/fG2auzG.png') !important;
}

/* 扩展 */
#extensionsMenuButton::before {
  background-image: url('https://iili.io/fG2azen.png') !important;
}

/* QR */
#quick-reply-rocket-button i::before {
  background-image: url('https://iili.io/fG2aAXf.png') !important;
}

/* 发送 */
#send_but::before {
  background-image: url('https://iili.io/fG2aAXf.png') !important;
}

/* 停止 */
#mes_stop i::before {
  background-image: url('https://iili.io/fG2aIbs.png') !important;
}


/*世界书界面*/
.wi-card-entry {
  border-radius: 0px !important; /* （可选)圆角数值 */
  padding: 20px;
}

.fillRight, .fillLeft, #WorldInfo, #floatingPrompt{
border-radius: 0px !important; /* （可选)圆角数值 */
}


/*主题界面*/
.drawer-content.openDrawer{
border-radius: 0px !important; 
}


/*大标题选项那种*/
#extensions_settings .inline-drawer-toggle.inline-drawer-header, #extensions_settings2 .inline-drawer-toggle.inline-drawer-header, #user-settings-block h4, .standoutHeader{
border-radius: 0px !important; /* （可选)圆角数值 */
background-image: linear-gradient(#222222);
    margin-bottom: 5px;
    border-radius: 10px;
    padding: 2px 5px;
    border-radius: 30px !important; /* （可选)圆角数值 */
    border: 1px solid var(--SmartThemeBorderColor);
    transition: all var(--animation-duration-2x);
}


/*引用文本*/
q {
  text-decoration: underline solid rgba(255, 255, 255, 0.7) 0px;
  text-underline-offset: 3px;
}



/* 聊天消息中的代码块 */
.mes_text pre code {
    background-color: rgba(255, 255, 255, 0.1) !important;
    border-radius: 0px !important;
    border: 0px !important;
}

/*引用框架*/
.mes_text blockquote,
.mes_reasoning blockquote {
    background-color: rgba(255, 255, 255, 0.2) !important;
    border-radius: 10px !important;
    border: 0px !important;
}


/*隐藏输入框原身文字*/
#send_textarea::placeholder {
    color: transparent !important;
    text-shadow: none !important; /* 移除可能存在的文字阴影 */
}

/*输入框自定义文案*/
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
    content: "-.. ..- -.-- .. .-- ..- . .-. -.. . -. .. .-.-.."; /* ""内自定义文案 */
    color: #fff; 
    opacity: 0.1;
    position: absolute; 
    left: 55%;
    top: 50%;
    transform: translate(-50%, -50%); 
    font-style: oblique; 
    font-size: 0.5em;  
    pointer-events: none; 
    z-index: 10; 
    white-space: nowrap; 
    overflow: hidden;
    text-overflow: ellipsis;
    max-width: calc(100% - 30px); 
}


/*正则*/
#saved_regex_scripts,
#saved_scoped_scripts,
#saved_preset_scripts,
#global-script-list,
#character-script-list {
  margin-right: 80px !important;
}



/*思维链*/
.mes_reasoning_summary {
  list-style: none; 
  cursor: pointer;
  display: flex !important;
  align-items: center;
}

.mes_reasoning_header {
  background: linear-gradient(45deg, rgba(255, 255, 255, 0.5), rgba(255, 255, 255, 0)); 
  border: 0px solid rgba(255, 255, 255, 1); /* 边框 */
  border-radius: 0px; /* 圆角 */
  padding: 0px 5px; /* 内边距 */
  top:40px;
  left:15px;
  z-index: 9999;
  transition: all 0.2s ease-in-out;
}

.mes_reasoning_summary:hover .mes_reasoning_header {
  transform: scale(1.02); 
  box-shadow: 0 0 10px rgba(255, 255, 255, 0.3); /* 辉光效果 */
}


/* 自定义思维链文案 */
.mes_reasoning_header_title {
  font-size: 0 !important;
}

.mes_reasoning_header_title::before {
  content: 'ᓚᘏᗢ'; /* 💾自定义文案 */
  font-size: 10px; /* 字体大小 */
  color: #fff; /* 字体颜色 */
  font-weight: bold; /* 粗体 */
}


.mes_reasoning_arrow {
  font-size: 0 !important;
}
.mes_reasoning_arrow::before {
  content: ''; /* 去除箭头 */
  font-size: 12px; 
  color: rgba(255, 255, 255, 0.5);
  display: inline-block; 
  transition: transform 0.3s ease;
}


/*ui背景*/
.drawer-content, 
#character_popup, 
#world_popup, 
#options ,
#select_chat_popup,
#extensionsMenu {
    background-color:#000;
    background-image: url('空') !important;
    background-repeat: no-repeat !important;
    background-position: center center !important;
    background-size: cover !important;
    box-shadow: inset 0 0 5px 3px rgba(255, 255, 255, 0.1) !important;
}



/*加载齿轮*/
#load-spinner {
    background-image: url('https://iili.io/fG2auzG.png') !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    background-size: contain !important;

    /* 取消旋转动画 */
    animation: none !important;

    /* 移除原图标内容 */
    border: none !important;
    border-radius: 0 !important;

    /* 设置合适的尺寸 */
    width: 64px !important;
    height: 64px !important;

    /* 隐藏原旋转元素 */
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
}

/* 确保原旋转器内容被隐藏 */
#load-spinner > * {
    display: none !important;
}

/* 如果原spinner有伪元素旋转动画，也要取消 */
#load-spinner::before,
#load-spinner::after {
    display: none !important;
    animation: none !important;
}
